using Microsoft.Data.Sqlite; using Workbench.Storage.Database;
namespace Workbench.Storage.Workers;
public sealed class CompletionPackageRepository(WorkbenchDatabase database){private readonly WorkbenchDatabase _d=database; public async Task AddAsync(Guid id,Guid executionId,Guid taskId,Guid revisionId,string report,string evidence, CancellationToken ct=default){await using var c=_d.CreateConnection();await c.OpenAsync(ct);var q=c.CreateCommand();q.CommandText="INSERT INTO worker_completion_packages(id,execution_id,task_id,executed_against_revision_id,final_report,evidence_json,created_at) VALUES($i,$e,$t,$r,$f,$v,$a)";q.Parameters.AddWithValue("$i",id.ToString());q.Parameters.AddWithValue("$e",executionId.ToString());q.Parameters.AddWithValue("$t",taskId.ToString());q.Parameters.AddWithValue("$r",revisionId.ToString());q.Parameters.AddWithValue("$f",report);q.Parameters.AddWithValue("$v",evidence);q.Parameters.AddWithValue("$a",DateTimeOffset.UtcNow.ToString("O"));await q.ExecuteNonQueryAsync(ct);}}
